 static float Smooth(float a,float b,float x){float t=Mathf.Clamp01((x-a)/(b-a));return t*t*(3-2*t);}
 public static float Bed(float x,float z,float original){if(!Art)return original;float pocket=Smooth(53,59,x)*(1-Smooth(102,114,x))*Smooth(58,68,z)*(1-Smooth(125,136,z));float ridgeX=78+Mathf.Sin(z*.13f)*3.5f;float ridge=Mathf.Exp(-Mathf.Pow((x-ridgeX)/6.5f,4));float far=Mathf.Exp(-Mathf.Pow((x-101)/6,4));float target=Mathf.Lerp(-15,-2.7f,ridge);target=Mathf.Max(target,Mathf.Lerp(-18,-5.5f,far));target+=Mathf.PerlinNoise(x*.12f,z*.12f)*.7f;return Mathf.Lerp(original,target,pocket);}
 GameDirector game;Transform root;OceanSurface sea;readonly List<Mesh> meshes=new List<Mesh>();readonly List<Material> mats=new List<Material>();readonly List<Collider> scenicColliders=new List<Collider>();readonly List<GameObject> trees=new List<GameObject>();int rocks,corals,ferns;string failure="";bool referenceView,grey;Vector3 savedBoat;Material greyMat;readonly Dictionary<Renderer,Material[]> colors=new Dictionary<Renderer,Material[]>();int beforeColliders;float benchmarkMs;
