 IEnumerator Start(){while(OceanSurface.Active==null||!OceanSurface.Active.BathymetryReady||Time.frameCount<12)yield return null;game=GetComponent<GameDirector>();sea=OceanSurface.Active;game.UI.Close();game.HarbourMenu=false;game.SetPause(false);yield return new WaitForEndOfFrame();beforeColliders=game.World.Root.GetComponentsInChildren<Collider>().Length;
