 void Build(){root=new GameObject("雾岬岛 · 立体岩岸与礁沟制作片段").transform;root.SetParent(game.World.Root,false);
  var ground=Resources.Load<Material>("CoastSlice/Ground");var sand=Resources.Load<Material>("CoastSlice/Sand");sand.SetFloat("_Triplanar",2);
  foreach(var r in game.World.Root.GetComponentsInChildren<MeshRenderer>()){
   if(r.name=="雾岬岛 · 可步行地形"){r.sharedMaterial=ground;WorldUV(r.GetComponent<MeshFilter>(),.15f);}
   if(r.name=="连续海床 · 仅视觉无碰撞")r.sharedMaterial=sand;
   if(r.name=="湿润露礁"&&r.transform.position.x>40&&r.transform.position.z>65&&r.transform.position.z<125){var b=r.bounds;r.enabled=false;foreach(var c in r.GetComponentsInChildren<Renderer>())c.enabled=false;Rock(new Vector3(b.center.x,-.95f,b.center.z),new Vector3(b.size.x*.96f,b.size.y+1.2f,b.size.z*.96f),17+r.transform.GetSiblingIndex(),false,false);}
   if(r.name=="环路踏石"){r.enabled=false;}
   if(r.name=="弯曲树干与枝条"||r.name=="风剪林冠与蕨叶")r.enabled=false;
  }
  ChunkSurfaces();
  // Existing walkable mesh remains intact; cliffs sit on the outer slopes, clear of the ring route and landing.
  Vector3[] coast={new Vector3(37,-1,118),new Vector3(40,-1,111),new Vector3(42,-1,104),new Vector3(41,-1,84),new Vector3(34,-1,75),new Vector3(28,-1,69)};
  for(int i=0;i<coast.Length;i++){Rock(coast[i],new Vector3(8.8f,5.3f+i%3*.5f,6.6f),38+i*23,true,true);}
  for(int i=0;i<15;i++){float z=70+i*3.7f,x=ShoreCycle.EastShoreX(z)-1.4f;if(Mathf.Abs(z-94)<5)continue;Rock(new Vector3(x,-.8f,z),new Vector3(2.6f,1.8f,2.1f),100+i,false,false);}
  // High-resolution bed follows exactly the function used to bake the water's bathymetry.
  const int nx=176,nz=180;var vertices=new Vector3[(nx+1)*(nz+1)];var tr=new int[nx*nz*6];for(int z=0;z<=nz;z++)for(int x=0;x<=nx;x++){float wx=43+x*66f/nx,wz=61+z*72f/nz;vertices[z*(nx+1)+x]=new Vector3(wx,sea.BottomHeight(wx,wz)-.015f,wz);}int at=0;for(int z=0;z<nz;z++)for(int x=0;x<nx;x++){int a=z*(nx+1)+x;tr[at++]=a;tr[at++]=a+nx+1;tr[at++]=a+1;tr[at++]=a+1;tr[at++]=a+nx+1;tr[at++]=a+nx+2;}MeshObject("连续细分礁台与深沟",vertices,tr,null,sand,4);
  BuildReefCommunities();var random=new System.Random(261020);
  Vector2[] spots={new Vector2(27,116),new Vector2(33,110),new Vector2(29,103),new Vector2(28,84),new Vector2(24,73),new Vector2(14,95)};
  for(int i=0;i<spots.Length;i++){var obj=Plant("island_tree_01",IslandTerrain.Point(spots[i].x,spots[i].y),6.5f+i%3,57+i*53);trees.Add(obj);}
  for(int i=0;i<100;i++){float x=18+(float)random.NextDouble()*23,z=68+(float)random.NextDouble()*55;if(IslandTerrain.Height(x,z)<.7f||NaturalCoast.RouteDistance(x,z)<2.7f||Protected(new Vector3(x,0,z),4))continue;Plant("fern_02",IslandTerrain.Point(x,z),.55f+(float)random.NextDouble()*.75f,i*27);ferns++;}
  // Timber uses one consistent textured material; structure and interaction colliders are retained.
  var timber=Resources.Load<Material>("CoastSlice/Timber");if(timber!=null){var paint=new Material(timber);paint.SetColor("_BaseColor",new Color(.40f,.52f,.49f));paint.SetFloat("_Desaturate",.6f);mats.Add(paint);foreach(var r in game.World.Root.GetComponentsInChildren<MeshRenderer>()){if(r.name=="铺板"||r.name=="桥桩"||r.name=="甲板条"||r.name=="木甲板")r.sharedMaterial=timber;if(r.name=="收尖船壳")r.sharedMaterial=timber;if(r.name=="舱顶")r.sharedMaterial=paint;}}
 }
 bool Protected(Vector3 p,float radius){p.y=0;foreach(var l in game.Expedition.Landings){var a=l.feet;a.y=0;var b=l.berth;b.y=0;if(Vector3.Distance(p,a)<radius||Vector3.Distance(p,b)<radius)return true;}foreach(var s in game.Expedition.Sites){var q=s.position;q.y=0;if(Vector3.Distance(p,q)<radius)return true;}return false;}
 void Rock(Vector3 p,Vector3 size,int seed,bool cliff,bool collision){var prefab=Resources.Load<GameObject>("CoastSlice/"+("boulder_01"));if(prefab==null){Require(false,"Missing rock prefab");return;}var obj=Instantiate(prefab,root);obj.name=cliff?"扫描岩岸断面":"扫描礁石";var rs=obj.GetComponentsInChildren<Renderer>();Bounds b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);obj.transform.localScale=Vector3.Scale(obj.transform.localScale,new Vector3(size.x/b.size.x,size.y/b.size.y,size.z/b.size.z));obj.transform.position-=Vector3.Scale(new Vector3(b.center.x,b.min.y,b.center.z),new Vector3(size.x/b.size.x,size.y/b.size.y,size.z/b.size.z));obj.transform.RotateAround(Vector3.zero,Vector3.up,seed%360);obj.transform.position+=p;foreach(var lod in obj.GetComponentsInChildren<LODGroup>())lod.ForceLOD(2);if(p.y+size.y<-.3f)SetLayer(obj,4);if(collision){var proxy=new GameObject("岩壁碰撞支撑");proxy.transform.SetParent(root,false);proxy.transform.SetPositionAndRotation(p+Vector3.up*(size.y*.45f),Quaternion.Euler(0,seed%360,0));var box=proxy.AddComponent<BoxCollider>();box.size=new Vector3(size.x*.72f,size.y*.8f,size.z*.72f);scenicColliders.Add(box);}rocks++;}
 GameObject Plant(string id,Vector3 p,float height,int angle){var obj=Instantiate(Resources.Load<GameObject>("CoastSlice/"+id),root);Bounds b=obj.GetComponentsInChildren<Renderer>()[0].bounds;foreach(var r in obj.GetComponentsInChildren<Renderer>())b.Encapsulate(r.bounds);float scale=height/Mathf.Max(.01f,b.size.y);obj.transform.localScale*=scale;obj.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z)*scale;obj.transform.RotateAround(Vector3.zero,Vector3.up,angle);obj.transform.position+=p;foreach(var lod in obj.GetComponentsInChildren<LODGroup>())lod.ForceLOD(-1);if(id=="island_tree_01")SetLayer(obj,4);return obj;}
 static void SetLayer(GameObject o,int layer){foreach(var t in o.GetComponentsInChildren<Transform>())t.gameObject.layer=layer;}
 void MeshObject(string name,Vector3[] v,int[] t,Color[] colors,Material mat,int layer){var mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.vertices=v;mesh.triangles=t;if(colors!=null)mesh.colors=colors;var uv=new Vector2[v.Length];for(int i=0;i<v.Length;i++)uv[i]=new Vector2(v[i].x*.16f,v[i].z*.16f);mesh.uv=uv;mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();meshes.Add(mesh);var obj=new GameObject(name);obj.layer=layer;obj.transform.SetParent(root,false);obj.AddComponent<MeshFilter>().sharedMesh=mesh;obj.AddComponent<MeshRenderer>().sharedMaterial=mat;}
 void WorldUV(MeshFilter filter,float scale){var mesh=Instantiate(filter.sharedMesh);var uv=new Vector2[mesh.vertexCount];var vertices=mesh.vertices;for(int i=0;i<uv.Length;i++){var q=filter.transform.TransformPoint(vertices[i]);uv[i]=new Vector2(q.x,q.z)*scale;}mesh.uv=uv;mesh.RecalculateTangents();filter.sharedMesh=mesh;meshes.Add(mesh);}
 void BatchObject(string name,ReefLifeGarden.Batch b,string shader){var mat=new Material(Shader.Find(shader));mats.Add(mat);var mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.SetVertices(b.v);mesh.SetColors(b.c);mesh.SetUVs(0,b.uv);mesh.SetTriangles(b.tr,0);mesh.RecalculateNormals();mesh.RecalculateBounds();meshes.Add(mesh);var obj=new GameObject(name);obj.layer=4;obj.transform.SetParent(root,false);obj.AddComponent<MeshFilter>().sharedMesh=mesh;var r=obj.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;}
 void Kelp(ReefLifeGarden.Batch b,Vector3 p,float height,int seed){if(height<1)return;for(int stem=0;stem<1;stem++){Vector3 end=p+new Vector3(Mathf.Sin(seed*1.73f)*.75f,height,Mathf.Cos(seed*.79f)*.55f);ReefDetails.Tube(b,p,end,.045f,.018f,new Color(.12f,.20f,.09f),new Color(.35f,.40f,.13f),5,seed);for(int j=1;j<9;j++){Vector3 start=Vector3.Lerp(p,end,j/10f);int a=b.v.Count;float side=j%2==0?1:-1;for(int k=0;k<=8;k++){float f=k/8f;Vector3 q=start+new Vector3(side*f*1.3f,Mathf.Sin(f*3.14f)*.28f-f*.12f,Mathf.Sin(seed+f)*.25f);float width=Mathf.Sin(f*Mathf.PI)*.21f;b.Vertex(q+Vector3.forward*width,new Color(.27f,.34f,.12f),new Vector2(j/10f,seed));b.Vertex(q-Vector3.forward*width,new Color(.34f,.40f,.16f),new Vector2(j/10f,seed));}for(int k=0;k<8;k++){int i=a+k*2;b.Tri(i,i+2,i+1);b.Tri(i+1,i+2,i+3);}}}}
 void Look(){var pipeline=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;if(pipeline!=null)pipeline.msaaSampleCount=2;if(!Check)gameObject.AddComponent<CoastFrameMonitor>();if(!Perf&&!Check){Application.targetFrameRate=60;QualitySettings.vSyncCount=0;}game.Camera.GetUniversalAdditionalCameraData().renderPostProcessing=true;var volume=root.gameObject.AddComponent<Volume>();volume.isGlobal=true;volume.priority=80;volume.sharedProfile=Resources.Load<VolumeProfile>("CoastSlice/Look");foreach(var l in FindObjectsOfType<Light>())if(l.type==LightType.Directional){l.transform.rotation=Quaternion.Euler(44,-35,0);l.intensity=2.1f;l.color=new Color(1,.91f,.73f);l.shadows=LightShadows.Soft;l.shadowBias=.035f;l.shadowNormalBias=.35f;}RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.39f,.49f,.55f);RenderSettings.ambientEquatorColor=new Color(.26f,.33f,.35f);RenderSettings.ambientGroundColor=new Color(.14f,.18f,.18f);RenderSettings.fog=false;Shader.SetGlobalFloat("_BayCoastSlice",1);}
 void Update(){if(game==null||Check||Perf)return;if(Input.GetKeyDown(KeyCode.F6)){referenceView=!referenceView;game.CameraFollow.enabled=!referenceView;if(referenceView)View(new Vector3(58,0,98),18);}if(Input.GetKeyDown(KeyCode.F7)&&root!=null){grey=!grey;if(greyMat==null){greyMat=new Material(Shader.Find("Deepsea/CoastRockLit"));greyMat.SetColor("_BaseColor",new Color(.5f,.5f,.5f));mats.Add(greyMat);}foreach(var r in root.GetComponentsInChildren<MeshRenderer>()){if(!colors.ContainsKey(r))colors[r]=r.sharedMaterials;r.sharedMaterials=grey?Array.ConvertAll(r.sharedMaterials,m=>greyMat):colors[r];}}}
 void View(Vector3 focus,float size){var rot=Quaternion.Euler(40,-12,0);game.Camera.transform.SetPositionAndRotation(focus-rot*Vector3.forward*90,rot);game.Camera.orthographicSize=size;}
 void Capture(string name){var texture=ScreenCapture.CaptureScreenshotAsTexture();if(!name.StartsWith("video")){int pink=0;foreach(var p in texture.GetPixels32())if(p.r>245&&p.b>245&&p.g<12)pink++;Require(pink<texture.width*texture.height*.001f,"Error shader pixels in "+name);}File.WriteAllBytes(Dir+"/"+(Baseline?"before-":"after-")+name+".png",texture.EncodeToPNG());Destroy(texture);}
 IEnumerator RunCheck(){Directory.CreateDirectory(Dir);game.Boat.AutomationInput=true;game.Boat.AutomationThrottle=0;game.Boat.AutomationRudder=0;game.Expedition.Explorer.AutomationInput=true;game.Expedition.Explorer.AutomationDirection=Vector3.zero;Screen.SetResolution(1600,900,FullScreenMode.Windowed);game.CameraFollow.enabled=false;foreach(var canvas in FindObjectsOfType<Canvas>())canvas.enabled=false;View(new Vector3(58,0,98),18);for(int i=0;i<20;i++)yield return new WaitForEndOfFrame();Capture("reference");View(new Vector3(38,2,109),14);yield return new WaitForEndOfFrame();Capture("cliffs");View(new Vector3(76,-1,96),18);yield return new WaitForEndOfFrame();Capture("reef");View(new Vector3(47,1,94),14);yield return new WaitForEndOfFrame();Capture("landing");
  if(Art){Require(rocks>25&&corals>100&&trees.Count>=5&&ferns>15,"Incomplete scene assets");foreach(var q in NaturalCoast.Route){float h=IslandTerrain.Height(q.x,q.y);Require(NaturalCoast.LandRelief(q.x,q.y)<.01f,"Walkable ring height changed");Require(Physics.Raycast(new Vector3(q.x,h+5,q.y),Vector3.down,10),"Route has no ground");foreach(var c in scenicColliders)Require(Vector3.Distance(c.ClosestPoint(new Vector3(q.x,h+.7f,q.y)),new Vector3(q.x,h+.7f,q.y))>.5f,"Cliff obstructs route");}}
  game.Boat.Moor(new Vector3(53,0,94),Quaternion.Euler(0,90,0));yield return new WaitForEndOfFrame();Require(game.Expedition.Disembark(),"Cannot land at east pier");for(int i=0;i<12;i++)yield return new WaitForEndOfFrame();Require(game.Expedition.BoardShip(),"Cannot board at east pier");game.Boat.Moor(new Vector3(55,0,94),Quaternion.Euler(0,20,0));game.Boat.Unmoor();
  View(new Vector3(58,0,98),18);float start=Time.realtimeSinceStartup;int count=180;for(int i=0;i<count;i++)yield return new WaitForEndOfFrame();benchmarkMs=(Time.realtimeSinceStartup-start)*1000/count;Capture("motion-later");
  string navigation="";if(Art){Time.captureFramerate=20;savedBoat=game.Boat.transform.position;var body=game.Boat.GetComponent<Rigidbody>();var probe=game.Boat.gameObject.AddComponent<CoastNavigationProbe>();float navigationStart=Time.time;game.Boat.AutomationThrottle=.45f;for(int i=0;i<120;i++){yield return new WaitForEndOfFrame();Capture("video-"+i.ToString("0000"));}game.Boat.AutomationThrottle=0;float distance=Vector3.Distance(savedBoat,game.Boat.transform.position);navigation="start="+savedBoat+" end="+game.Boat.transform.position+" distance="+distance+" simulatedSeconds="+(Time.time-navigationStart)+" physicsSteps="+probe.steps+" paused="+game.Paused+" moored="+game.Boat.Moored+" kinematic="+body.isKinematic+" contacts="+string.Join(",",probe.contacts);Debug.Log("COAST_NAVIGATION "+navigation);Require(distance>3,"Boat did not navigate: "+navigation);Time.captureFramerate=0;}

  var result=new Result{passed=failure=="",detail=failure==""?"Imported scene rendered; ring ground, landing and boarding verified. Visual quality requires image review.":failure,navigation=navigation,rocks=rocks,corals=corals,trees=trees.Count,ferns=ferns,newColliders=scenicColliders.Count,meanFrameMs=benchmarkMs};File.WriteAllText(Dir+"/"+(Baseline?"before":"after")+"-result.json",JsonUtility.ToJson(result,true));Debug.Log("COAST_SLICE_CHECK "+JsonUtility.ToJson(result));Application.Quit(failure==""?0:1);
 }
 [Serializable]class Result{public bool passed;public string detail,navigation;public int rocks,corals,trees,ferns,newColliders;public float meanFrameMs;}
 void OnDestroy(){Application.logMessageReceived-=Log;Time.captureFramerate=0;foreach(var m in meshes)if(m!=null)Destroy(m);foreach(var m in mats)if(m!=null)Destroy(m);Shader.SetGlobalFloat("_BayCoastSlice",0);}
}
